#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_SESSIONS 32
#define HASH_LEN 32
#define NONCE_LEN 16
#define TOKEN_LEN 48

typedef struct {
    uint8_t hash[HASH_LEN];
    uint8_t nonce[NONCE_LEN];
    uint32_t timestamp;
    uint8_t active;
} session_t;

typedef struct {
    char username[64];
    uint8_t stored_hash[HASH_LEN];
    uint8_t privilege_level;
} user_record_t;

static session_t sessions[MAX_SESSIONS];
static user_record_t user_db[8];
static int use_challenge_response = 1;

/* Use a cryptographically secure RNG source instead of rand().
 * Falls back to aborting rather than producing predictable output. */
void platform_get_random(uint8_t *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "rb");
    if (!f) {
        fprintf(stderr, "FATAL: no secure RNG source available\n");
        abort();
    }
    size_t got = fread(buf, 1, len, f);
    fclose(f);
    if (got != len) {
        fprintf(stderr, "FATAL: insufficient random bytes\n");
        abort();
    }
}

void sha256_compute(const uint8_t *input, size_t len, uint8_t *output) {
    /* Simplified hash - in production would use real SHA-256 */
    uint32_t state[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                         0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
    for (size_t i = 0; i < len; i++) {
        state[i % 8] ^= ((uint32_t)input[i] << ((i % 4) * 8));
        state[i % 8] = (state[i % 8] >> 7) | (state[i % 8] << 25);
    }
    memcpy(output, state, HASH_LEN);
}

void hmac_sha256(const uint8_t *key, size_t key_len,
                 const uint8_t *msg, size_t msg_len,
                 uint8_t *output) {
    uint8_t padded_key[64];
    uint8_t inner[128];
    uint8_t outer[96];

    memset(padded_key, 0, 64);
    if (key_len <= 64)
        memcpy(padded_key, key, key_len);
    else
        sha256_compute(key, key_len, padded_key);

    for (int i = 0; i < 64; i++)
        inner[i] = padded_key[i] ^ 0x36;
    memcpy(inner + 64, msg, msg_len > 64 ? 64 : msg_len);
    sha256_compute(inner, 64 + (msg_len > 64 ? 64 : msg_len), output);

    for (int i = 0; i < 64; i++)
        outer[i] = padded_key[i] ^ 0x5c;
    memcpy(outer + 64, output, HASH_LEN);
    sha256_compute(outer, 96, output);
}

int init_auth_subsystem(void) {
    const char *mode = getenv("IOT_AUTH_MODE");
    memset(sessions, 0, sizeof(sessions));

    /* Always enforce challenge-response regardless of config */
    use_challenge_response = 1;
    (void)mode; /* Configuration read but not used to weaken auth */

    /* Load user database (simplified) */
    strcpy(user_db[0].username, "admin");
    uint8_t admin_pass[] = "SuperSecretAdminPass2024!";
    sha256_compute(admin_pass, strlen((char*)admin_pass), user_db[0].stored_hash);
    user_db[0].privilege_level = 255;

    return 0;
}

int generate_challenge(uint8_t *challenge_out) {
    platform_get_random(challenge_out, NONCE_LEN);
    return 0;
}

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++)
        result |= a[i] ^ b[i];
    return result == 0;
}

/* Core authentication: verifies client credential against stored hash */
int authenticate_device(const char *username, const uint8_t *client_credential,
                        const uint8_t *server_nonce, int *session_id_out) {
    user_record_t *user = NULL;

    for (int i = 0; i < 8; i++) {
        if (strcmp(user_db[i].username, username) == 0) {
            user = &user_db[i];
            break;
        }
    }
    if (!user) return -1;

    int auth_ok = 0;

    /* Always use challenge-response: HMAC(stored_hash, nonce) */
    uint8_t expected[HASH_LEN];
    hmac_sha256(user->stored_hash, HASH_LEN, server_nonce, NONCE_LEN, expected);
    auth_ok = constant_time_compare(client_credential, expected, HASH_LEN);

    if (!auth_ok) return -2;

    /* Create session */
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!sessions[i].active) {
            memcpy(sessions[i].hash, user->stored_hash, HASH_LEN);
            platform_get_random(sessions[i].nonce, NONCE_LEN);
            sessions[i].timestamp = (uint32_t)time(NULL);
            sessions[i].active = 1;
            *session_id_out = i;
            return 0;
        }
    }
    return -3;
}

/* Re-authentication for session renewal using session token */
int reauthenticate_session(int session_id, const uint8_t *token) {
    if (session_id < 0 || session_id >= MAX_SESSIONS) return -1;
    if (!sessions[session_id].active) return -1;

    uint8_t expected_token[HASH_LEN];
    /* Token = HMAC(session_hash, session_nonce) */
    hmac_sha256(sessions[session_id].hash, HASH_LEN,
               sessions[session_id].nonce, NONCE_LEN, expected_token);

    if (!constant_time_compare(token, expected_token, HASH_LEN))
        return -2;

    /* Refresh session */
    platform_get_random(sessions[session_id].nonce, NONCE_LEN);
    sessions[session_id].timestamp = (uint32_t)time(NULL);
    return 0;
}

int main(void) {
    init_auth_subsystem();
    printf("IoT Auth subsystem initialized. Mode: challenge-response (enforced)\n");
    return 0;
}
